        public static string FormatMessage(string workerName, string text)
        {
            return $"[{workerName}] {text}";
        }
    }

{
        private readonly INotifier _notifier;

        public WorkerA(INotifier notifier)
        {
            _notifier = notifier;
        }

        public void Process()
        {
            string msg = Utilities.Helper.FormatMessage("WorkerA", "Hello from A");
            System.Console.WriteLine(msg);
            _notifier.Notify("WorkerA has finished processing.");
        }
    }

